sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.docType = "";
    c.notes = "";
    c.uploading = false;

    c.upload = function() {
        if (!c.docType) return;
        c.uploading = true;
        c.server.get({
            action: "upload_complete",
            app_id: c.data.applicationId,
            doc_type: c.docType,
            notes: c.notes
        }).then(function(r) {
            c.data.successMsg = r.data.successMsg;
            c.docType = "";
            c.notes = "";
            c.uploading = false;
            $scope.$broadcast("ibar.documents.refresh");
        }, function() {
            c.uploading = false;
        });
    };
};

sp_widget.script:
(function() {
  data.documents = [];
  data.uploadEnabled = true;
  data.applicationId = "";
  data.applicationName = "";

  try {
    data.applicationId = input ? input.app_id || $sp.getParameter("app_id") || "" : $sp.getParameter("app_id") || "";

    if (!data.applicationId) {
      data.uploadEnabled = false;
      return;
    }

    var appGr = new GlideRecord("x_1433041_identi_0_application");
    if (appGr.get(data.applicationId)) {
      data.applicationName = appGr.getValue("name");
    }

    if (input && input.action === "upload_complete") {
      data.successMsg = "Document uploaded successfully.";
      return;
    }
  } catch (e) {
    gs.error("IBAR Document Upload widget error: " + e.message);
  }
})();
